import {esc,head,panel,button,badge,link,note,table,empty,date} from './view.js';
import {ruleEditor,rulePreviewMarkup} from './experimental-ui.js';

const statuses={draft:'Bản nháp',validated:'Đã kiểm tra',published:'Đã công bố',archived:'Đã ẩn'};
const patternNames={orthogonal:'Thẳng',diagonal:'Chéo',king:'8 hướng',knight:'Nhảy chữ L'};
const kindNames={rock:'Búa',paper:'Lá',scissors:'Kéo'};
const status=r=>badge(r.status==='published'?'completed':r.status==='archived'?'aborted':'pending',statuses[r.status]);
const code=value=>`<pre class="report-json">${esc(typeof value==='string'?value:JSON.stringify(value,null,2))}</pre>`;
export function changeValue(value){
 if(value===null||value===undefined)return 'Không có';
 if(typeof value==='boolean')return value?'Bật':'Tắt';
 if(typeof value!=='object')return String(value);
 if(value.square)return `${value.square} · ${value.kind==='energy'?'năng lượng':'kiểm soát'} +${value.gain}`;
 if(value.pattern){const f=value.filter||{},filter=[(f.kinds||[]).map(k=>kindNames[k]||k).join(', '),(f.piece_ids||[]).join(', ')].filter(Boolean).join(' / ')||'mọi quân';return `${patternNames[value.pattern]||value.pattern} · tầm ${value.range} · ${filter} · ${value.cost} năng lượng · hồi ${value.cooldown} lượt`;}
 return JSON.stringify(value);
}
function catalogCards(s){
 const c=s.rulesetCatalog,admin=s.user?.role==='admin';
 return c.items.length?`<div class="real-card-grid addon-catalog">${c.items.map(r=>`<article class="real-card"><div class="section-head">${status(r)}<span>v${r.version}</span></div><h3>${esc(r.definition.name)}</h3><p>${r.definition.zones.length} vùng · ${r.definition.modifiers.length} mẫu đi · Khiên ${r.definition.shield.enabled?'bật':'tắt'}</p><small class="mono">${esc((r.hash||'Bản nháp').slice(0,12))}</small><div class="page-actions">${link('rulesets/'+r.id,'Chi tiết luật','small')}${admin?button('Mở trình sửa','rule-open',`data-id="${r.id}"`,'small'):''}${admin&&['draft','validated'].includes(r.status)?button('Kiểm tra & công bố','rule-release',`data-id="${r.id}"`,'small primary'):''}</div>${admin?`<div class="table-actions">${button('Tạo phiên bản mới','rule-clone',`data-id="${r.id}"`,'small')}${r.status!=='archived'?button('Ẩn khỏi thư viện','rule-archive',`data-id="${r.id}"`,'small'):''}</div>`:''}</article>`).join('')}</div>`:empty('Chưa có ruleset add-on',admin?'Chọn mẫu bên dưới hoặc nhập gói JSON.':'BTC chưa công bố luật mới. Các giải tiêu chuẩn vẫn dùng OTTv2.');
}
export function addonPage(s){
 const c=s.rulesetCatalog;if(!c)return empty('Đang tải ruleset…');
 const admin=s.user?.role==='admin',r=s.ruleEditing,d=s.ruleDraft||r?.definition||Object.values(c.presets||{})[0];
 let html=head('Ruleset add-on','Luật bổ sung cho OTTv2. Mỗi giải dùng một phiên bản cố định; các đội đọc luật và benchmark trước khi đăng ký.',admin?button('Bản nháp mới','rule-new'):button('Starter SDK v3','experimental-starter'));
 html+=note('Experimental · Các mô-đun hiện có: năng lượng, vùng kiểm soát, mẫu đi theo filter và Khiên. SDK v3 nhận toàn bộ cấu hình trong init; legal_actions thay đổi theo trạng thái từng lượt.');
 if(admin)html+=panel('Cho phép sử dụng add-on',`<label class="switch-label"><input type="checkbox" role="switch" aria-label="Bật Ruleset add-on" data-action="experimental-toggle" ${c.enabled?'checked':''}><span class="switch-track" aria-hidden="true"></span><strong>${c.enabled?'Đang bật':'Đang tắt'}</strong></label><p>Công bố luật và bật công tắc để tạo benchmark, luyện tập hoặc giải mới. Khi tắt, các giải đã tạo và replay giữ nguyên snapshot.</p>`);
 else if(!c.enabled)html+=note('BTC đang tắt việc tạo job add-on mới. Bạn vẫn có thể đọc luật, tải SDK và thử nước đi tại đây.');
 html+=panel(admin?'Thư viện ruleset':'Ruleset đã công bố',catalogCards(s));
 if(!admin)return html;
 html+=panel('Nhập gói add-on',`<p>Nhập definition JSON hoặc gói xuất từ thư viện. Server kiểm tra giới hạn và mô phỏng cho hai màu; có thể công bố trong cùng một thao tác.</p><form id="addon-import-form" class="real-form"><label class="field"><span>Tệp cấu hình JSON (tối đa 32 KiB)</span><input class="input" type="file" name="addon-file" accept=".json,application/json" required></label><label class="check-field"><input type="checkbox" name="publish-import">Công bố ngay sau khi kiểm tra thành công</label><div class="form-error" role="alert"></div><button class="btn primary" type="submit">Nhập & kiểm tra</button></form>`);
 html+=`<div class="addon-modules">${(c.modules||[]).map(m=>`<article><strong>${esc(m.name)}</strong><p>${esc(m.description)}</p></article>`).join('')}</div>`;
 html+=`<div class="rule-workbench"><section class="panel"><div class="section-head"><h2>${r?esc(r.definition.name)+' · v'+r.version:'Bộ luật mới'}</h2>${r?status(r):''}</div><p class="muted">1. Chọn mẫu và chỉnh cấu hình → 2. Lưu bản nháp → 3. Kiểm tra & công bố → 4. Tạo giải.</p><div class="page-actions">${Object.entries(c.presets||{}).map(([id,p])=>button(p.name,'rule-preset',`data-preset="${id}"`,'small')).join('')}</div>${r?.hash?note('Phiên bản đã công bố được giữ nguyên. Tạo phiên bản mới để thay đổi cấu hình và ghi chú.'):''}<div id="rule-editor">${ruleEditor(d,r,s.ruleNotes??r?.release_notes??'')}</div>${r?`<div class="page-actions">${['draft','validated'].includes(r.status)?button('Kiểm tra & công bố bản đã lưu','rule-release',`data-id="${r.id}"`,'primary'):''}${r.status==='published'&&c.enabled?link('competitions?ruleset='+r.id,'Tạo giải với luật này','primary'):r.status==='published'?note('Bật công tắc ở đầu trang để tạo giải hoặc job với luật này.'):''}${link('rulesets/'+r.id,'Xem như đội thi','small')}${button('Xuất gói JSON','rule-package',`data-id="${r.id}"`,'small')}</div>`:''}${r?.validation?note('Đã kiểm tra schema, giới hạn action/frame và smoke hai màu. Đây chưa phải đánh giá cân bằng luật.'):''}</section><section class="panel rule-preview"><h2>Xem thử trên server</h2><div id="rule-preview">${rulePreviewMarkup(s.rulePreview,s.rulePreviewActions?.length||0)}</div></section></div>`;
 return html;
}
export function addonDetailPage(s){
 const r=s.ruleDetail;if(!r)return empty('Không tìm thấy ruleset');
 const c=r.contract,d=r.definition,admin=s.user?.role==='admin';
 const actions=button('Gói luật & tài liệu','rule-kit',`data-id="${r.id}"`)+button('Starter nộp bot','rule-starter',`data-id="${r.id}"`)+link('rulesets','Thư viện');
 const compared=c.compared_to.name+(c.compared_to.version?' · v'+c.compared_to.version:'');
 let html=head(d.name+' · v'+r.version,'Ruleset add-on · Experimental · SDK v3 / rules-v1',actions);
 html+=`<div class="competition-summary">${status(r)}<span>Hash <code>${esc(c.hash.slice(0,16))}</code></span><span>${date(r.published_unix_ms||r.created_unix_ms)}</span></div>`;
 if(r.status==='archived')html+=note('Luật này đã ẩn khỏi lựa chọn mới. Tài liệu giữ lại để đối chiếu các giải và replay đã dùng phiên bản này.');
 if(r.status!=='published'&&r.status!=='archived')html+=note('Bản nháp chỉ BTC xem được. Đội thi sẽ thấy sau khi công bố.');
 if(r.validation)html+=panel('Kết quả kiểm tra',note(r.validation.summary)+(r.validation.warnings||[]).map(note).join('')+`<p class="muted">Schema, giới hạn action/frame và smoke hai màu. Kết quả này chưa chứng nhận cân bằng hoặc hiệu năng bot.</p>`);
 html+=panel('BTC ghi chú',`<p class="addon-release-notes">${esc(r.release_notes||'Chưa có ghi chú riêng. Xem bảng thay đổi và cấu hình bên dưới.')}</p>`);
 html+=panel('Thay đổi so với '+compared,c.changes.length?table(['Thay đổi','Trước','Hiện tại'],c.changes.map(x=>`<tr><td><strong>${esc(x.label)}</strong></td><td>${esc(changeValue(x.before))}</td><td>${esc(changeValue(x.after))}</td></tr>`)):note('Cơ chế giống phiên bản đối chiếu; xem tên và ghi chú của BTC.'));
 const zones=d.zones.length?table(['Ô','Loại vùng','Thưởng cuối lượt'],d.zones.map(z=>`<tr><td class="mono">${esc(z.square)}</td><td>${z.kind==='energy'?'Năng lượng':'Kiểm soát'}</td><td>+${z.gain}</td></tr>`)):note('Không có vùng đặc biệt.');
 const mods=d.modifiers.length?table(['Kỹ năng','Mẫu đi / filter','Năng lượng','Hồi chiêu'],d.modifiers.map(m=>`<tr><td><code>${esc(m.id)}</code></td><td>${esc(patternNames[m.pattern])} · tầm ${m.range}<div class="muted">${esc(changeValue(m).split(' · ').slice(2,3).join(''))}</div></td><td>${m.cost}</td><td>${m.cooldown} lượt của đội</td></tr>`)):note('Chỉ có nước đi thường.');
 const goals=[['base_capture','Chiếm căn cứ'],['type_eliminated','Loại hết một loại quân'],['no_legal_moves','Đối thủ hết nước hợp lệ']].map(([key,label])=>`<li>${esc(label)}: <strong>${d.victory[key]?'bật':'tắt'}</strong></li>`).join('');
 html+=`<div class="real-two-col">${panel('Vùng & năng lượng',`<p>Ban đầu <strong>${d.energy.initial}</strong> · Tối đa <strong>${d.energy.cap}</strong></p>${zones}<p class="muted">Thưởng cho bên vừa đi nếu còn chiếm vùng, vào cuối lượt. Năng lượng bị chặn ở giới hạn; điểm kiểm soát được tích lũy.</p>`)}${panel('Mẫu đi & mục tiêu',`<p>${esc(c.movement.base)}</p>${mods}<p>Khiên: <strong>${d.shield.enabled?`bật · ${d.shield.cost} năng lượng · ${d.shield.duration} lượt của đội`:'tắt'}</strong></p><ul>${goals}<li>Kiểm soát: <strong>${d.victory.control_target?d.victory.control_target+' điểm để thắng':'tắt'}</strong></li><li>Hết toàn bộ quân: luôn thua.</li></ul><p class="muted">Ưu tiên: căn cứ → hết quân → hết một loại → kiểm soát → hết nước. ${esc(c.movement.cooldown)}</p>`)}</div>`;
 html+=panel('Giao thức & cách chuẩn bị bot',note(c.compatibility.classic_bot)+`<ol><li>Tải starter nộp bot, thay phần chọn nước bằng thuật toán của đội.</li><li>Đọc <code>init.payload.ruleset.definition</code> và kiểm tra hash/capability khi ready.</li><li>Chọn <code>id</code> trong <code>payload.legal_actions</code> ở mỗi observation. Dùng simulator SDK để tìm kiếm trạng thái sau nước đi.</li><li>Nộp ZIP với SDK v3, benchmark đúng ruleset và thời gian của giải; chọn bản đạt chuẩn để dự giải.</li></ol><p>${esc(c.protocol.transport)}</p><p>${esc(c.protocol.identity)}</p><p>${esc(c.protocol.legal_actions)}</p><p>${esc(c.protocol.clock)}</p><details class="addon-details"><summary>Ready và action mẫu</summary>${code(c.examples.ready)}${code(c.examples.action)}<p class="muted">Sao chép envelope khi chạy thật. ID trong ví dụ chỉ dùng với observation mẫu.</p></details><details class="addon-details"><summary>Observation payload ban đầu</summary>${code(c.examples.observation_payload)}</details><details class="addon-details"><summary>Definition đầy đủ & hash</summary>${code(d)}${code(c.hash)}</details><p><a href="/api/v1/experimental/guide">Đọc chi tiết giao thức SDK v3</a> · <a href="/api/v1/rulesets/schema">JSON Schema cấu hình</a></p><div class="page-actions">${!admin&&r.status==='published'&&s.rulesetCatalog?.enabled?link('benchmark?ruleset='+r.id,'Benchmark với luật này','primary'):''}${admin&&r.status==='published'&&s.rulesetCatalog?.enabled?link('competitions?ruleset='+r.id,'Tạo giải với luật này','primary'):''}${button('Xuất gói JSON','rule-package',`data-id="${r.id}"`)}</div>`);
 html+=panel('Thử nước đi hợp lệ',`<p>Server mô phỏng trực tiếp định nghĩa này. Mỗi bước cập nhật legal_actions, năng lượng và trạng thái; tối đa 32 bước, không tạo job hoặc thay kết quả thi đấu.</p><div id="team-rule-preview">${s.rulePlay?rulePreviewMarkup(s.rulePlay,s.rulePlayActions?.length||0,'rule-play'):button('Bắt đầu mô phỏng','rule-play-reset','','primary')}</div>`);
 return html;
}
